5: import { currencyFormatter, isAuthenticated, routes } from "@nabstore/utils";
6: import { Anchor, Button, Typography } from "@nabstore/styleguide";
7: import { BestOffersFragment } from "@nabstore/mfe-products";
8: import CartProduct from "../../components/CartProduct";
9: 
10: const Cart = ({
11:   addProductToCartAction,
12:   cleanCartAction,
13:   removeProductFromCartAction,
14: }) => {
15:   const dispatch = useDispatch();
16:   const navigate = useNavigate();
17:   const { cart } = useSelector((state) => ({
18:     cart: state.cart,
19:   }));
20:   const [total, setTotal] = useState(0);
21: 
22:   useEffect(() => {
23:     setTotal(
24:       cart.produtos.reduce(
25:         (prev, actual) => prev + actual.qtd * actual.precoUnit,
26:         0
27:       )
28:     );
29:   }, [cart]);
30: 
