3: const CART_KEY = "cart";
4: 
5: const initialState = localStorage.getItem(CART_KEY)
6:   ? JSON.parse(localStorage.getItem(CART_KEY))
7:   : {
8:       produtos: [],
9:       enderecoEscolhido: undefined,
10:       cartaoEscolhido: undefined,
11:     };
12: 
13: export const cartSlicer = createSlice({
14:   name: "cart",
15:   initialState,
16:   reducers: {
17:     addProduto: (state, action) => {
18:       const newProdutos = state.produtos.filter(
19:         (prod) => prod.id !== action.payload.id
20:       );
21: 
22:       const newCart = {
23:         ...state,
24:         produtos: [
25:           ...newProdutos,
26:           {
27:             id: action.payload.id,
28:             qtd: action.payload.qtd,
29:             precoUnit: action.payload.precoUnit,
30:             nome: action.payload.nome,
31:           },
32:         ],
33:       };
34: 
35:       localStorage.setItem(CART_KEY, JSON.stringify(newCart));
36: 
37:       return newCart;
38:     },
39:     removeProduto: (state, action) => {
40:       const newCart = {
41:         ...state,
42:         produtos: state.produtos.filter(
43:           (prod) => prod.id !== action.payload.id
44:         ),
45:       };
46: 
47:       localStorage.setItem(CART_KEY, JSON.stringify(newCart));
48: 
49:       return newCart;
50:     },
51:     selectEndereco: (state, action) => {
52:       const enderecoEscolhido = {
53:         logradouro: action.payload.logradouro,
54:         bairro: action.payload.bairro,
55:         cidade: action.payload.cidade,
56:         numero: action.payload.numero,
57:         uf: action.payload.uf,
58:         cep: action.payload.cep,
59:         id: action.payload.id,
60:       }
61: 
62:       const newState = {
63:         ...state,
64:         enderecoEscolhido
65:       }
66:       localStorage.setItem(CART_KEY, JSON.stringify(newState));
67: 
68:       return newState;
69:     },
70:     selectCartao: (state, action) => {
71:       const cartaoEscolhido = {
